SELECT 1 AS ok SETTINGS enable_filesystem_cache=0,use_page_cache_with_distributed_cache=0,force_read_through_distributed_cache=0,max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames